// ---------- Квесты и диалоги (v0.3) ----------
'use strict';

// Повторяемые поручения: каждый день у жителей своя нужда. Дают золото и опыт.
const TASKS = {
  smith:     { item: 'ore', n: 3, name: 'руды', gold: 45, xp: 25, ask: 'Горн жрёт руду, я жру хлеб, круг замкнулся. Три куска из шахты. Заплачу. Не щедро — щедрость это к покойникам, они отдают всё сразу.', ok: 'Руда как руда. Держи. И не смотри так, будто мы теперь родня.' },
  healer:    { item: 'herb', n: 4, name: 'травы', gold: 35, xp: 20, ask: 'Отвары кончились, а бабки в деревне — нет. Четыре пучка. И не жуй по дороге: я узнаю, у тебя язык позеленеет.', ok: 'Свежая. Вот тебе. И ведро у порога вынеси за огород, раз всё равно идёшь. Что значит «я не нанимался»? Тут никто не нанимался.' },
  innkeeper: { item: 'mushroom', n: 4, name: 'грибов', gold: 30, xp: 18, ask: 'Похлёбку варить не из чего, а едят так, будто война. Четыре гриба. Ядовитые тоже беру — их подаю тем, кто спорит о политике.', ok: 'Годится. Спасибо. Нет, кровать всё равно платная.' },
  hunter:    { item: 'pelt', n: 2, name: 'шкур', gold: 55, xp: 30, ask: 'Ремни вязать не из чего. Две шкуры. И не рассказывай, как добыл, — я как раз ем.', ok: 'Ровные. Держи серебро. Считать при мне не надо, я обидчивый.' },
  guard:     { item: 'bandage', n: 2, name: 'бинтов', gold: 28, xp: 16, ask: 'Стража латает друг друга тряпьём и надеждой. Пара бинтов. Надежда, кстати, тоже кончилась ещё в прошлом году.', ok: 'Сгодится. Спасибо. Проходи, не задерживай очередь. Очереди нет, но принцип есть.' },
  elder:     { item: 'wood', n: 3, name: 'дров', gold: 40, xp: 22, ask: 'Общинный нужник просел на левый бок. Доски у нас дороже совести, а совесть у нас дешёвая. Три полена. Это, если хочешь, тоже спасение деревни — только пахнет честнее.', ok: 'Годится. Держи. И мусор у калитки прихвати — ты же всё равно туда идёшь.' }
};
const Tasks = {
  state(id) { G.tasks = G.tasks || {}; return G.tasks[id] || (G.tasks[id] = { day: -1, taken: false }); },
  // задание обновляется раз в день
  available(id) { const t = TASKS[id], st = this.state(id); if (!t) return false; if (st.taken) return true; return st.day !== G.day; },
  option(id) {
    const t = TASKS[id]; if (!t) return null; const st = this.state(id);
    if (!st.taken) return { label: 'Есть подработка?', go: () => { st.taken = true; st.day = G.day; log(`Поручение: принести ${t.n} ${t.name}`, 'gold'); SFX.quest(); return { text: t.ask, opts: [{ label: 'Хорошо', main: true, go: () => 'close' }] }; } };
    const have = countItem(t.item);
    if (have >= t.n) return { label: `Отдать ${t.n} ${t.name}`, main: true, go: () => {
      removeItem(t.item, t.n); const gold = Math.round(t.gold * (1 + (G.rep || 0) * 0.05)); G.gold += gold; gainXp(t.xp); G.rep = (G.rep || 0) + 1;
      st.taken = false; st.day = G.day; log(`+${gold} золота за поручение`, 'gold'); SFX.quest();
      return { text: t.ok + ` (+${gold} золота)`, opts: [{ label: 'Уйти', go: () => 'close' }] }; } };
    return { label: `Поручение: ${have}/${t.n} ${t.name}`, go: () => ({ text: `Жду ${t.n} ${t.name}. Пока ${have}.`, opts: [{ label: 'Ладно', go: () => 'close' }] }) };
  }
};
const Quests = {
  journal() {
    const q = G.quests, f = G.flags, out = [], c = countItem;
    if (q.seal === 1) out.push(['Печать крипты', f.bossDead ? (c('key_seal') ? 'Ключ у тебя. Освин ждёт — но выяснилось, что вариантов три, потому что в этой деревне даже у двери три мнения. Отдать. Сжечь у Ильвы. Или послушать, что бормочет алтарь, — спойлер: ничего хорошего, но опыт дадут.' + (q.locket === 1 ? ' И да, в крипте всё ещё стоит девушка и ждёт. Она ждала двести лет, подождёт и пока ты обнесёшь сундуки.' : '') : 'Ворлат повержен. Теперь надо найти ключ. Разумеется, он не выпал из него сразу — это было бы удобно, а удобно тут не бывает.') : 'Спуститься в крипту под часовней, убить некроманта и принести ключ. Староста говорит, Печать «сорвали» — пассивный залог, любимая грамматическая форма всех, кто что-то натворил.']);
    if (q.seal === 2) out.push(['Печать крипты ✓', f.ending === 'osvin' ? 'Освин запер крипту и признался, что сам её и отпер. Деревня спасена от беды, которую деревня сама себе и устроила. Это, в общем, вся история человечества, только в масштабе одного двора.' : f.ending === 'ilva' ? 'Ключ сгорел, крипта осела, мёртвые легли навсегда. Никто не сказал спасибо словами длиннее одного слога.' : 'Ты оставил ключ себе. Пепел шепчет тебе по ночам, соседи переходят на другую сторону улицы, а цены в лавках выросли. Слава — штука дорогая, платит за неё всегда покупатель.']);
    if (q.wolves === 1) out.push(['Волки перевала', `Три волчьи шкуры кузнецу (${Math.min(3, c('pelt'))}/3). Волки на западе и за воротами. Волки, кстати, тоже считают, что это их перевал, и у них аргументы весомее.`]);
    if (q.wolves === 2) out.push(['Волки перевала ✓', 'Брандт отдал меч и сразу же перестал считать себя должником. Быстро он.']);
    if (q.herbs === 1) out.push(['Настой знахарки', `Три пучка моховника Ильве (${Math.min(3, c('herb'))}/3). Растёт у скал и у воды. Выглядит как трава. Это и есть трава.`]);
    if (q.herbs === 2) out.push(['Настой знахарки ✓', 'Ильва отдала бабкин амулет. Бабка, по слухам, была не подарок, но амулет — подарок.']);
    if (q.merchant === 1) out.push(['Пропавший торговец', c('letter') ? 'Письмо найдено. Две строчки, одна из которых — «не разбойники». Люди умеют быть краткими, только когда это максимально неудобно.' : 'Торговец Эйнар пропал на тропе за восточными воротами. Все уверены, что это разбойники. Все всегда уверены.']);
    if (q.merchant === 2) out.push(['Пропавший торговец ✓', f.arrowTruth && f.martaTold ? 'Марта знает правду. Правда не помогла никому, но зато теперь она у неё есть — как ведро без дна.' : 'Марта узнала, что Эйнар мёртв. Похлёбка в тот вечер была пересолена.']);
    if (q.arrow === 1) out.push(['Стрела в спину', c('ledger') ? 'Книга Эйнара: «Ансгар. 40 монет. Не отдаёт». Поговорить с охотником Ансгаром.' : 'Письмо говорит: не разбойники. Эйнар шёл к охотнику Ансгару. Осмотреть его стоянку — сундук у палатки.']);
    if (q.arrow === 2) out.push(['Стрела в спину ✓', f.ansgarDead ? 'Ансгар мёртв.' : f.ansgarGone ? 'Ансгар ушёл с перевала.' : 'Ты взял деньги Ансгара за молчание.']);
    if (q.bandits === 1) out.push(['Разбойники на тропе', f.chiefDead ? 'Атаман мёртв. Доложить Оле. Оле, скорее всего, найдёт повод заплатить меньше.' : f.chiefGone ? 'Хродгар увёл шайку. Сказать Оле — и посмотреть, как он вычтет за «не тот результат».' : 'Лагерь у скал на северо-востоке. Оле хочет голову. Голова, по слухам, хочет обратно.']);
    if (q.bandits === 2) out.push(['Разбойники на тропе ✓', f.oleChiefDead ? 'Оле понял, что ты соврал, вычел за это половину и всё равно заплатил. Гримхолд в одном человеке.' : f.banditsBribed ? 'Оле поверил, что атаман сбежал. Оле верит всему, что позволяет не идти в лес.' : 'Тропа безопасна. Ровно до следующего голодного года.']);
    if (q.cousin === 1) out.push(['Двоюродный брат', f.chiefGone ? 'Хродгар ушёл. Сказать Свену, пока он не выпил столько, что забудет, кто такой Хродгар.' : 'Свен просит уговорить брата уйти живым. Уговаривать придётся золотом: семейные чувства тут идут по прейскуранту.']);
    if (q.cousin === 2) out.push(['Двоюродный брат ✓', f.chiefGone ? 'Свен отдал дедов перстень и заказал ещё кружку — на этот раз от радости, что технически другое.' : 'Свен узнал, что брат мёртв, и заказал две кружки. Одну — брату.']);
    if (q.mine === 1) out.push(['Старая шахта', f.queenDead ? (c('pickaxe_old') ? 'Кирка найдена. Нести Хальвару в таверну — он там, где и был, где и будет.' : 'Матка мертва. Кирка где-то в логове, под слоем того, что раньше было обедом.') : 'В шахте завелись пауки размером с собаку. Собаки, справедливости ради, тоже были против.']);
    if (q.mine === 2) out.push(['Старая шахта ✓', f.minerGone && !f.mineDone && !c('pickaxe_old') ? 'Хальвар изгнан из Гримхолда. Кирка его отца — твоя, если найдёшь её в логове Матки.' : 'Хальвар оставил кирку тебе.']);
    if (q.twoInMine === 1) out.push(['Двое в шахте', 'Записка: «Хальвар завалил вход. Скажите Грете». Двадцать лет она пролежала в темноте и терпеливо ждала, пока кто-нибудь придёт всё испортить. Дождалась.']);
    if (q.twoInMine === 2) out.push(['Двое в шахте ✓', f.mineTruth === 'greta' ? 'Грета знает, как погиб её муж.' : f.mineTruth === 'osvin' ? 'Освин изгнал Хальвара из Гримхолда.' : 'Ты сохранил тайну Хальвара.']);
    if (q.moon === 1) out.push(['Лунный цветок', `Два лунных цветка Ильве (${Math.min(2, c('moonflower'))}/2). Растут в самой глубине шахты, потому что всё ценное растёт там, где темно, сыро и кусаются.`]);
    if (q.moon === 2) out.push(['Лунный цветок ✓', 'Ильва научила тебя чувствовать магию тоньше.']);
    if (q.bear === 1) out.push(['Медведь-шатун', f.bearDead ? 'Медведь мёртв. Отнести коготь Ансгару, пока не начал пахнуть.' : 'Медведь не лёг на зиму и оттого зол — состояние, знакомое каждому, кого будили рано.']);
    if (q.bear === 2) out.push(['Медведь-шатун ✓', f.bearNoAnsgar ? 'Ансгара больше нет на перевале. Коготь шатуна остался тебе — он и сам по себе оберег.' : 'Ансгар сделал из когтя оберег.']);
    if (q.locket === 1) out.push(['Неупокоенная', c('locket') ? 'Медальон найден. Отнести его призраку в западный зал. Да, ты бегаешь по склепу с бижутерией. Мы оба знали, к чему всё идёт.' : 'Призрак просит найти медальон в южных залах. Двести лет она искала сама, но у неё нет рук, а у тебя нет отговорок.']);
    if (q.locket === 2) out.push(['Неупокоенная ✓', f.elinorLost ? 'Крипта запечатана. Элинор осталась под камнем — навсегда.' : 'Элинор обрела покой и оставила тебе знание Ледяной стрелы.']);
    if (q.treasure === 1) out.push(['Клад разбойников', 'Крестик у мёртвых сосен, рядом с медвежьим логовом. Разбойники, видимо, считали медведя надёжнее банка. По-своему они правы.']);
    if (q.treasure === 2) out.push(['Клад разбойников ✓', 'Клад выкопан. Лопата затупилась, спина болит, золото не пахнет. Всё как обещали.']);
    if (!out.length) out.push(['Пусто, как в кладовой', 'Заданий нет. Никто тебя не ждёт, никто тебе ничего не должен, мир прекрасно обходился без тебя триста лет. Сходи к старосте — он у площади, делает вид, что занят.']);
    return out;
  },
  check() {
    const f = G.flags, q = G.quests, hint = (k, cond, msg) => { if (cond && !f[k]) { f[k] = 1; log(msg, 'gold'); SFX.quest(); } };
    hint('sealHint', q.seal === 1 && countItem('key_seal'), 'Ключ Печати у тебя. Освин ждёт — но есть и другие пути.');
    hint('wolfHint', q.wolves === 1 && countItem('pelt') >= 3, 'Три шкуры собраны. Кузнец ждёт.');
    hint('herbHint', q.herbs === 1 && countItem('herb') >= 3, 'Моховника хватит. Отнеси Ильве.');
    hint('letterHint', q.merchant === 1 && countItem('letter'), 'Письмо Эйнара: «Не разбойники». Марта должна его увидеть.');
    hint('ledgerHint', countItem('ledger'), 'Книга Эйнара. Последняя запись — про Ансгара.');
    hint('chiefHint', q.bandits === 1 && f.chiefDead, 'Атаман мёртв. Доложи стражнику Оле.');
    hint('pickHint', q.mine === 1 && countItem('pickaxe_old'), 'Кирка Хальвара найдена. Он в таверне.');
    hint('moonHint', q.moon === 1 && countItem('moonflower') >= 2, 'Два лунных цветка. Ильва будет рада.');
    hint('bearHint', q.bear === 1 && countItem('bear_claw'), 'Коготь шатуна у тебя. Ансгар ждёт у костра.');
    hint('locketHint', q.locket === 1 && countItem('locket'), 'Медальон Элинор. Она ждёт в западном зале крипты.');
    hint('mapHint', countItem('treasure_map') && q.treasure === 0, 'Карта разбойников! Крестик у мёртвых сосен. Нужна лопата.');
    if (countItem('treasure_map') && q.treasure === 0) q.treasure = 1;
    if (countItem('ledger') && q.arrow === 0) q.arrow = 1;
    if (countItem('note_mine') && q.twoInMine === 0) { q.twoInMine = 1; }
  },
  marker() {
    if (!L || !G) return null;
    const q = G.quests, c = countItem, cell = (x, z) => ({ x: cw(x), z: cw(z) }), id = L.id, f = G.flags, M = [];
    if (id === 'village') {
      if (q.seal === 0) M.push(cell(16, 11));
      if (q.seal === 1) M.push(c('key_seal') ? cell(16, 11) : cell(8, 10));
      if (q.wolves === 1 && c('pelt') >= 3) M.push(cell(18, 16));
      if ((q.herbs === 1 && c('herb') >= 3) || (q.moon === 1 && c('moonflower') >= 2)) M.push(cell(11, 24));
      if ((q.merchant === 1 && c('letter')) || (q.mine === 1 && c('pickaxe_old')) || (q.cousin === 1 && f.chiefGone) || (q.twoInMine === 1)) M.push(cell(30, 22));
      if (q.bandits === 1 && (f.chiefDead || f.chiefGone)) M.push(cell(32, 6));
      if ((q.merchant === 1 && !c('letter')) || (q.bandits === 1 && !f.chiefDead && !f.chiefGone) || (q.mine === 1 && !c('pickaxe_old')) || (q.bear === 1 && !c('bear_claw')) || (q.moon === 1 && c('moonflower') < 2) || (q.arrow === 1) || (q.cousin === 1 && !f.chiefGone) || q.treasure === 1) M.push(cell(33, 5));
      if (q.wolves === 1) M.push(cell(7, 29));
    } else if (id === 'tavern') {
      if ((q.merchant === 1 && c('letter')) || (q.arrow === 2 && !f.martaTold)) M.push(cell(7, 2));
      if ((q.mine === 1 && c('pickaxe_old')) || q.twoInMine === 1) M.push(cell(2, 6));
      if (q.cousin === 1 && f.chiefGone) M.push(cell(11, 5));
    } else if (id === 'forest') {
      if (q.merchant === 1 && !c('letter')) M.push(cell(16, 13));
      if ((q.bandits === 1 && !f.chiefDead && !f.chiefGone) || (q.cousin === 1 && !f.chiefGone && !f.chiefDead)) M.push(cell(37, 8));
      if (q.arrow === 1) M.push(c('ledger') ? cell(11, 36) : cell(9, 35));
      if (q.bear === 1 && !c('bear_claw')) M.push(cell(32, 31));
      if (q.bear === 1 && c('bear_claw')) M.push(cell(11, 36));
      if (q.treasure === 1 && L.def.treasure) M.push(cell(L.def.treasure.x, L.def.treasure.z));
      if ((q.mine === 1 && !c('pickaxe_old')) || (q.moon === 1 && c('moonflower') < 2)) M.push(cell(22, 4));
      if ((q.merchant === 1 && c('letter')) || (q.mine === 1 && c('pickaxe_old')) || (q.bandits === 1 && (f.chiefDead || f.chiefGone)) || (q.moon === 1 && c('moonflower') >= 2)) M.push(cell(1, 20));
    } else if (id === 'crypt') {
      if (q.locket === 1) M.push(c('locket') ? cell(5, 16) : cell(20, 25));
      if (c('key_seal')) M.push(cell(19, 1));
      else if (f.bossDead) M.push(cell(35, 35));
      else { const locked = !!L.locks['31,27']; if (locked && !c('key_rusty') && !G.killed['d_sk4']) M.push(cell(7, 19)); else if (locked) M.push(cell(31, 27)); else M.push(cell(31, 33)); }
    } else if (id === 'mine') {
      if (c('pickaxe_old') || (q.moon === 1 && c('moonflower') >= 2)) M.push(cell(20, 1));
      else if (q.mine === 1) M.push(f.queenDead ? cell(31, 34) : cell(31, 33));
      else if (q.moon === 1) M.push(cell(36, 22));
    }
    return M[0] || null;
  }
};

const Dialog = {
  npc: null,
  start(id) { this.npc = id; this.show(this.node(id)); },
  show(node) {
    if (!node) { UI.hide('dlg'); return; }
    $('dlgName').textContent = node.name || this.npcName(); const dt = $('dlgText'); if (node.html) dt.innerHTML = node.html; else dt.textContent = node.text; dt.scrollTop = 0; setTimeout(() => { $('dlgMore').style.display = dt.scrollHeight > dt.clientHeight + 4 ? 'block' : 'none'; }, 0); dt.onscroll = () => { if (dt.scrollTop + dt.clientHeight >= dt.scrollHeight - 4) $('dlgMore').style.display = 'none'; };
    const o = $('dlgOpts'); o.innerHTML = ''; o.classList.toggle('grid', node.opts.length >= 3 && window.innerWidth > 700);
    for (const opt of node.opts) { const b = document.createElement('button'); b.className = 'ubtn' + (opt.main ? ' main' : ''); b.textContent = opt.label; b.onclick = () => { SFX.click(); const r = opt.go(); if (r === 'keep') return; if (r === 'close' || !r) UI.hide('dlg'); else this.show(r); }; o.appendChild(b); }
    if (typeof Voice !== 'undefined' && node.text && node.voice !== null) Voice.speak(node.text, node.voice || this.npc);
    UI.show('dlg');
  },
  npcName() { for (const w in WORLDS) { const n = WORLDS[w].npcs.find(n => n.id === this.npc); if (n) return n.name; for (const e of WORLDS[w].enemies) if (e.talk === this.npc) return e.name; } return { vorlat: 'Ворлат', intro: 'Пепельный перевал', chief: 'Атаман Хродгар' }[this.npc] || 'Рассказчик'; },
  node(id) {
    const q = G.quests, f = G.flags, c = countItem, bye = { label: 'Уйти', go: () => 'close' };
    const say = (text, opts) => ({ text, opts: opts || [bye] });
    const startQ = (key, name, text) => ({ label: text || 'Согласен', main: true, go: () => { q[key] = 1; log('Новое задание: ' + name, 'gold'); SFX.quest(); return 'close'; } });
    const done = (key, name, fn, text, after) => ({ label: text, main: true, go: () => { q[key] = 2; fn(); log('Задание выполнено: ' + name, 'gold'); SFX.quest(); Quests.check(); return after ? say(after) : null; } });
    const cycle = (arr, n) => arr[Math.floor(G.playTime / (n || 40)) % arr.length];
    const sealCrypt = () => { f.cryptSealed = 1; if (q.locket === 1) { q.locket = 2; f.elinorLost = 1; log('Элинор осталась под камнем.', 'red'); } };
        if (id === 'intro') return { name: 'Пепельный перевал', text: 'Позади обрушился перевал. Это не метафора и не сюжетный приём — просто камни. Правда, упали они ровно в тот момент, когда ты сюда пришёл, и ровно так, чтобы назад пути не было. Совпадение, конечно.\n\nВнизу дымит Гримхолд: тридцать домов, одна таверна, один нужник на всех и триста лет упрямства.\n\nГоворят, здесь неспокойно. Говорят, мёртвые под часовней перестали лежать смирно. Ещё говорят, что гора горела, пепел не остыл и вообще всё плохо.\n\nТебе, разумеется, никто не рад. Тебя тут не звали, тебе тут ничего не должны, и первое, что тебе скажут, — это цена за кровать.', opts: [{ label: 'Спуститься в долину', main: true, go: () => { log('Староста у площади, к северу. Делает вид, что занят.', 'blue'); UI.toast('Иди на север — к площади'); return 'close'; } }, { label: 'А можно я обратно?', go: () => ({ text: 'Нет.\n\nЗа спиной — камни в два твоих роста. Ты можешь простоять тут до утра, изучая их фактуру, и это, кстати, будет самое безопасное занятие за всю игру. Но еда кончится, вода кончится, а камни — нет.', opts: [{ label: 'Ладно, вниз', main: true, go: () => { log('Староста у площади, к северу. Делает вид, что занят.', 'blue'); return 'close'; } }] }) }] };
    // ---- Ворлат перед боем ----
    if (id === 'vorlat') return { name: 'Ворлат', text: 'Стой. Дай угадаю: тебя послал Освин, ты пришёл за ключом, и по дороге ты обшарил тут каждый гроб. Не оправдывайся, я слышал, как ты гремел крышками. Двести лет тишины, и тут — ты.\n\nОсвин приходил ночью. Хотел услышать отца. Я дал ему это. Отец сказал ему ровно то, что говорят все мёртвые, если их разбудить: «уходи». Мёртвые вообще неразговорчивы. У них было время подумать, и они пришли к выводу, что говорить не о чем.\n\nПечать держит не нас, а пепел под горой. Отдашь ключ Освину — нас снова запрут. Сожжёшь — уснём навсегда. Оставишь себе — будешь слышать то же, что и я, и поверь, это не музыка.\n\nА теперь давай закончим. Я двести лет сторож при двери, которую никто не открывал. Даже смерть оказалась работой.', opts: [{ label: 'К бою', main: true, go: () => 'close' }] };
    // ---- Алтарь: третья концовка ----
    if (id === 'altar') return { name: 'Алтарь Печати', text: 'Ключ в руке холодеет. Из-под алтаря идёт шёпот — не слова, а пепел, который помнит, как горел, и хочет об этом поговорить.\n\n«Оставь себе. Мы дадим тебе огонь, который не гаснет. И ночь, которая не кончается».\n\nВ переводе с древнего на человеческий: тебе предлагают силу, бессонницу и репутацию человека, рядом с которым не садятся за стол. Двое из трёх пунктов — минусы. Но огонь-то хороший.', opts: [{ label: 'Вслушаться в шёпот', go: () => { f.altarAsked = 1; q.seal = 2; f.ending = 'keep'; f.endingKeep = 1; if (!G.spells.includes('ash')) G.spells.push('ash'); G.maxHp += 15; log('Изучено заклинание: Пепельный взрыв', 'blue'); log('Задание выполнено: Печать крипты. Гримхолд будет помнить это.', 'gold'); SFX.boom(); P.shake = 1; return say('Шёпот стихает. Ключ тёплый и остывать не собирается.\n\nГде-то у часовни завыло. Ночи в Гримхолде станут беспокойнее, цены — выше, а взгляды — короче. Зато ты теперь умеешь взрывать пепел. Обмен, прямо скажем, в твою пользу: страдать будут в основном другие.'); } }, { label: 'Зачаровать вещь', go: () => { Craft.open('altar'); return 'close'; } }, { label: 'Отойти от алтаря', go: () => 'close' }] };
    // ---- Староста ----
    if (id === 'elder') {
      const lore = { label: 'Расскажи о Гримхолде', go: () => say((f.minerGone ? 'Хальвар ушёл ночью. Я не спрашивал куда. Кто-то сказал ему то, что я знал двадцать лет и молчал — потому что молчать дешевле.\n\n' : '') + 'Гримхолд стоит триста лет. Сначала на серебре, потом на овцах, теперь на упрямстве — это единственный ресурс, который у нас не кончается, потому что его никто не покупает.\n\nЧасовню поставили над криптой, где хоронили тех, кого не хотели видеть на общем кладбище: самоубийц, чужаков и одну девушку, которая любила не того. Печать держала их внизу.\n\nДержала.', [{ label: 'Назад', go: () => this.node('elder') }]) };
      if (f.ending === 'keep') return say(cycle(['Ты не отдал ключ. Ночью я слышу, как дышит гора, и это, поверь, хуже, чем когда храпит жена.', 'Люди тебя боятся. Дети перестали играть у часовни. Один плюс: у часовни стало чище.', 'Уходи с площади. Пожалуйста. И мусор захвати, раз идёшь.']), [bye]);
      if (q.seal === 0) return say('Странник. Чужих у нас не было с позапрошлой осени, и тот оказался сборщиком податей, так что радость сдержанная.\n\nДорога завалена, назад ты не уйдёшь. Это плохая новость для тебя и умеренно хорошая для нас: у нас беда, а рабочих рук нет.\n\nТри ночи назад из-под часовни завыло, и мёртвые перестали лежать смирно. Кто-то сорвал Печать с крипты. Кто — неизвестно. Совершенно неизвестно. Никому.', [{ label: 'Что за Печать?', main: true, go: () => say('Ключ запирал крипту двести лет. Хранил его Ворлат — при жизни священник, после смерти... тоже в некотором роде при исполнении.\n\nПринеси ключ — запру обратно. Плачу золотом и тем, что найдётся в кладовой. Заранее предупреждаю: в кладовой мыши.\n\nВход — дверь часовни, к северо-западу. Нет, я не пойду с тобой. Я староста, у меня спина.', [{ label: 'Я спущусь в крипту', main: true, go: () => { q.seal = 1; log('Новое задание: Печать крипты', 'gold'); SFX.quest(); return say('Зелья у Ильвы, меч у Брандта, и не жалей золота — покойникам скидок не делают. В таверне переночуешь бесплатно, я скажу Марте. Она возьмёт с тебя за еду. Она всегда берёт за еду.\n\nИ последнее: на стенах крипты есть надписи. Не читай их вслух. Один парень прочитал. Мы до сих пор не знаем, где он.'); } }, { label: 'Мне нужно подумать', go: () => 'close' }]) }, lore, bye]);
      if (q.seal === 1) {
        if (c('key_seal')) {
          const give = { label: 'Отдать ключ', main: true, go: () => { removeItem('key_seal'); q.seal = 2; f.ending = 'osvin'; sealCrypt(); G.gold += 200; addItem('potion_hp', 3); addItem('rune_life', 1); log('+200 золота', 'gold'); log('Задание выполнено: Печать крипты', 'gold'); SFX.quest(); return say(f.confronted ? 'Спасибо, что не сказал остальным. Я запру крипту на рассвете и больше никогда не спущусь.\n\nГримхолд — твой дом, странник. Покуда стоит перевал.' : 'Крипта будет запечатана на рассвете. Держи — из кладовой, как обещал.\n\nГримхолд — твой дом, странник. Покуда стоит перевал.'); } };
          const confront = { label: 'Ты сам снял Печать', go: () => { f.confronted = 1; return say('...Ворлат сказал тебе. Ну конечно. Мёртвые вообще ужасно болтливы, когда речь о чужих грехах.\n\nДа. Я взял ключ из отцовского тайника и спустился ночью. Хотел одно слово. Отец умирал, злясь на меня, и двадцать лет я репетировал, что он ответит.\n\nОн ответил «уходи». Двадцать лет ожидания ради шести букв.\n\nА потом я не смог запереть дверь: руки тряслись. Вот и всё величие нашей беды, странник. Один трус, одна дверь и одно слово. Мёртвые встали не из-за древнего зла, а потому что немолодой человек не смирился с тем, что его не любили.', [give, { label: 'Ты заплатишь за это деревней', go: () => say('Заплачу. Только не ключом — с ключом делай что хочешь: сожги, отдай, повесь на шею. Меня будешь находить у площади. Каждый день. Я никуда не денусь, в этом и наказание.', [bye]) }, bye]); } };
          const opts = [give]; if (c('diary3') || f.vorlatTalk) opts.push(confront); opts.push({ label: 'Пока оставлю себе', go: () => 'close' });
          return say('Это... ключ. Холодный, как совесть у сборщика податей. Ты сделал то, на что не решился никто из нас, — правда, никто из нас и не пытался, так что планка была невысокой.\n\nОтдай — запру на рассвете.' + (q.locket === 1 ? '\n\n...Ты говоришь, там кто-то ещё ждёт? Девушка в белом? Не знаю такой. Не хочу знать.' : f.ghostGone ? '\n\n...И спасибо за сестру. Отец не сказал мне, где её положили. Теперь я знаю.' : ''), opts);
        }
        return say(f.bossDead ? 'Вой стих. Ключ нашёл? Нет? Тогда чего ты стоишь на площади с таким лицом, будто уже всё сделал.' : 'Вход в крипту — дверь часовни, к северо-западу. Держись света, не спускайся без зелий и не читай надписи вслух. Я это говорил каждому, кто спускался. Каждому.', [lore, Tasks.option('elder'), bye].filter(Boolean));
      }
      return say(f.ending === 'ilva' ? 'Гора вздохнула — я слышал ночью. Крипты больше нет. Отца больше нет. Совсем.\n\nНаверное, так правильно. Не знаю. Иди, странник. И мусор захвати.' : 'Печать держится, ночью тихо, деревня вернулась к своему любимому занятию — сплетням.\n\nСкучно? У Брандта, Ильвы и в таверне всегда найдётся работа: тут спасителя мира с удовольствием отправят за грибами. Оле у ворот опять жалуется на разбойников — он жалуется профессионально, это его основной навык.', [lore, Tasks.option('elder'), bye].filter(Boolean));
    }
    // ---- Кузнец ----
    if (id === 'smith') {
      const trade = { label: 'Торговать', go: () => { Shop.open('smith'); return 'close'; } };
      const craft = { label: 'Про ремесло', go: () => say('Плавильня и наковальня у стены. Руду из шахты, дрова с любого дерева — топор продам, дерево бесплатно, дерево у нас единственное, что бесплатно.\n\nДве руды и дрова в горн — слиток. Слиток на наковальню — клинок. Бей по светлому месту, три раза. Промахнёшься — выйдет кривое, но я его всё равно назову «авторским».\n\nСломается — неси. Починю за слиток. Бесплатно чиню только собственную репутацию.') };
      let job;
      if (q.wolves === 0) job = { label: 'Есть работа?', go: () => say('Волки. Спустились с перевала и режут овец у западного леса. Овцы, надо сказать, тоже не гении: бегут строго в сторону волка.\n\nТри шкуры — и отдам стальной меч, который ковал себе. Себе я выкую ещё, у меня руки. У тебя — сроки.', [startQ('wolves', 'Волки перевала'), { label: 'Не сейчас', go: () => 'close' }]) };
      else if (q.wolves === 1) job = c('pelt') >= 3 ? done('wolves', 'Волки перевала', () => { removeItem('pelt', 3); addItem('sword_steel'); }, 'Отдать шкуры', 'Три шкуры. Держи. Сталь горная, не подведёт — в отличие от людей, которые её заказывают.') : { label: 'Про волков', go: () => say(`Шкуры. Три. Пока ${c('pelt')}. Волки в западном лесу, за домами, и за воротами их хватает.`) };
      else job = { label: 'Про меч', go: () => say('Не затупился? То-то. Хорошая сталь.') };
      const w = wdef(); const greet = !w ? 'Голыми руками тут живут ровно до первой волчьей стаи. Купи хоть кинжал, я даже сделаю вид, что это выгодная покупка.' : w.dmg < 10 ? 'Клинок у тебя ржавый, как моя совесть, и такой же бесполезный. Купи новый — доживёшь до старости. Или выкуй сам, руда в шахте лежит даром. Даром, потому что там пауки.' : w.dmg >= 20 ? 'Ого. С таким клинком я бы и сам сходил в крипту. Не пойду, но подумал бы — а это, по нашим меркам, подвиг.' : 'А, странник. Меч, кольчуга, кирка? Могу продать всё три, но советую начать с того, чем реже бьют по себе.';
      return say(greet, [trade, job, craft, Tasks.option('smith'), bye].filter(Boolean));
    }
    // ---- Знахарка ----
    if (id === 'healer') {
      const trade = { label: 'Торговать', go: () => { Shop.open('healer'); return 'close'; } };
      const alch = { label: 'Про зелья', go: () => say('Котёл у крыльца, пользуйся, только не мой в нём ноги — был прецедент.\n\nДва пучка моховника — зелье здоровья. Грибы с моховником — противоядие. Гриб и моховник — согревающий отвар: пьётся тяжело, действует надёжно, наутро всё равно стыдно. Лунный цветок — для маны, но за ним лезть под землю, где пауки.\n\nПомешивай вовремя — выйдет двойная порция. Не помешаешь — выйдет то, что мы потом всей деревней закапываем.') };
      let job;
      if (q.herbs === 0) job = { label: 'Нужна помощь?', go: () => say('Моховник. По краям долины, у скал и у воды. Три пучка.\n\nПринесёшь — отдам бабкин амулет. Бабка была женщина тяжёлого нрава и лёгкой руки: половину деревни вылечила, вторую половину прокляла. Амулет бережёт силу духа — видимо, потому что вобрал весь её характер.', [startQ('herbs', 'Настой знахарки', 'Соберу'), { label: 'Не сейчас', go: () => 'close' }]) };
      else if (q.herbs === 1) job = c('herb') >= 3 ? done('herbs', 'Настой знахарки', () => { removeItem('herb', 3); addItem('amulet'); }, 'Отдать моховник', 'Свежий, с росой. Держи амулет. Носи не снимая — не потому что магия, а потому что потеряешь, а второго нет.') : { label: 'Про моховник', go: () => say(`Три пучка. Пока ${c('herb')}. У скал и у воды.`) };
      else if (q.moon === 0) job = { label: 'Есть ещё дело?', go: () => say('Есть. Лунный цветок растёт только в темноте, глубоко в шахте. Два цветка — и я покажу, как тянуть ману прямо из воздуха.\n\nТам пауки размером с собаку. Возьми противоядие. Нет, в подарок не дам: если я буду раздавать зелья каждому, кто идёт умирать, я разорюсь к четвергу.', [startQ('moon', 'Лунный цветок', 'Принесу'), { label: 'Не сейчас', go: () => 'close' }]) };
      else if (q.moon === 1) job = c('moonflower') >= 2 ? done('moon', 'Лунный цветок', () => { removeItem('moonflower', 2); addItem('potion_mp', 3); G.skills.destr += 4; G.maxMp += 10; if (!G.spells.includes('heal')) G.spells.push('heal'); log('Навык «Разрушение» +4, запас маны +10. Изучено: Исцеление', 'blue'); }, 'Отдать цветы', 'Светятся... Закрой глаза. Чувствуешь? Вот так течёт мана. Теперь сможешь латать себя сам — и перестанешь наконец опустошать мою полку.') : { label: 'Про лунный цветок', go: () => say(`Два цветка. Пока ${c('moonflower')}. В шахте, в самой глубине — там, где светится.`) };
      else job = { label: 'Про амулет', go: () => say('Греет? Значит, жив. Не греет — значит, ты в крипте, и это не проблема амулета.') };
      const opts = [trade, job, alch];
      if (q.seal === 1 && c('key_seal')) opts.push({ label: 'Про Ключ Печати', go: () => say('Дай посмотреть... Холодный. Освин, конечно, велит запереть крипту обратно — он всю жизнь решает проблемы, закрывая за ними дверь.\n\nНо Печать держит не мёртвых, а пепел под горой. Пепел и не даёт им спать. Сожги ключ в моём котле: гора вздохнёт, крипта осядет, мёртвые лягут навсегда.\n\nОсвин этого не переживёт — там его отец. Деревня переживёт. Деревня вообще переживает всё, кроме неурожая.', [{ label: 'Сжечь ключ', main: true, go: () => { removeItem('key_seal'); q.seal = 2; f.ending = 'ilva'; sealCrypt(); G.maxMp += 20; addItem('rune_life', 2); addItem('potion_mp', 2); log('Задание выполнено: Печать крипты', 'gold'); SFX.quest(); SFX.boom(); P.shake = 1; return say('...Слышишь? Гора вздохнула. Больше никто не поднимется — ни хорошие, ни плохие, ни те, кому просто было что сказать.\n\nВозьми руны жизни, из запасов. Тебе нужнее: ты из тех, кто умирает часто.\n\nОсвину скажу сама. Это будет короткий разговор.'); } }, { label: 'Не сейчас', go: () => 'close' }]) });
      opts.push(bye);
      return say(f.ending === 'keep' ? 'К котлу не подходи. От тебя пахнет пеплом — тем самым. И не делай вид, что не понимаешь: я тридцать лет нюхаю то, что люди приносят на сапогах.' : f.ending === 'ilva' ? 'Крипта осела, ночью тихо, как в колыбели. Спасибо, странник. Скидки не будет, но спасибо искреннее.' : 'Заходи. Зелья, травы, перевязки. За крипту не берусь: там лечить уже некого, а воскрешать я не умею и, честно говоря, не одобряю.', [...opts.slice(0, -1), Tasks.option('healer'), opts[opts.length - 1]].filter(Boolean));
    }
    // ---- Стражник ----
    if (id === 'guard') {
      let job;
      if (q.bandits === 0 && (f.chiefGone || f.chiefDead)) job = { label: 'Про разбойников', go: () => say(f.chiefDead ? 'Хродгар мёртв? Кто-то опередил меня. Ладно — тропа чиста, и это главное.' : 'Хродгар увёл шайку за перевал, говорят. Не знаю, кто его уговорил. Спасибо, если ты.') };
      else if (q.bandits === 0) job = { label: 'Что за разбойники?', go: () => say('Шайка Хродгара. Сидят у скал на северо-востоке и грабят всех, кто идёт к дальним выпасам.\n\nПочему не иду сам? Мне платят за ворота. Вот эти. Я стою у них. Это, если вдуматься, вся моя должностная инструкция, и я её выполняю блестяще.\n\nЗа голову атамана — сто пятьдесят монет и щит из оружейной. Оружейная — это сундук у меня дома, но название красивое.', [startQ('bandits', 'Разбойники на тропе', 'Я разберусь'), { label: 'Не моё дело', go: () => 'close' }]) };
      else if (q.bandits === 1) {
        if (f.chiefDead) job = done('bandits', 'Разбойники на тропе', () => { G.gold += 150; addItem('shield_iron'); log('+150 золота', 'gold'); }, 'Атаман мёртв', 'Голову видел? Нет? Ладно, верю. Проверять — это в лес идти, а я, как ты помнишь, при воротах. Держи щит и монеты.');
        else if (f.chiefGone) job = done('bandits', 'Разбойники на тропе', () => { G.gold += 50; log('+50 золота', 'gold'); }, 'Хродгар увёл шайку', 'Ушли? Живыми? Хм. Тропа чиста, спорить не буду, но платил я за голову, а голова уехала вместе с остальным.\n\nПолсотни. И не делай такое лицо — в контракте было написано «голова». Контракта не было, но было бы написано.');
        else if (f.chiefBribed) job = done('bandits', 'Разбойники на тропе', () => { G.gold += 50; f.banditsBribed = 1; log('+50 золота', 'gold'); }, 'Атаман сбежал', 'Сбежал? Странно. Хродгар не из пугливых, он из тех, кто пугает.\n\nЛадно. Полсотни за хлопоты. Остальное — за то, что я делаю вид, будто верю.');
        else job = { label: 'Про атамана', go: () => say('Лагерь у скал, северо-восток. Их четверо и атаман. В лоб не лезь — выманивай по одному, как делают все умные люди и ни один герой.\n\nИ вот что: в палатке у Хродгара сундук. Там не только золото. Откуда знаю? Не спрашивай, а то придётся отвечать.') };
      } else if (f.banditsBribed && f.chiefDead && !f.oleChiefDead) job = { label: 'Атаман мёртв', main: true, go: () => { f.oleChiefDead = 1; G.gold += 100; addItem('shield_iron'); log('+100 золота', 'gold'); SFX.quest(); return say('Мёртв? Ты же говорил — сбежал. А голова тогда чья?..\n\nЗнаешь что, не отвечай. Я тут стою у ворот двенадцать лет именно потому, что не задаю вторых вопросов.\n\nДержи щит и сотню. Полсотни удержу за враньё. Считай это налогом на творческий подход.'); } };
      else job = { label: 'Как дела на тропе?', go: () => say(f.banditsBribed ? (f.chiefDead ? 'Тихо. Теперь — по-настоящему.' : 'Тихо. Хотя пастух говорит, видел Хродгара у скал. Показалось, наверное.') : 'Тихо. Пастухи снова ходят к дальним выпасам. Спасибо, странник.') };
      return say(q.bandits === 2 ? 'А, гроза разбойников. Проходи. Только не рассказывай подробностей, у меня обед.' : 'Стой! ...А, это ты, с перевала. Проходи.\n\nЗа воротами лес, в лесу разбойники, в разбойниках — недостаток воспитания. Гляди в оба. Я бы пошёл с тобой, но кто тогда будет стоять здесь и говорить «стой» тем, кто и так остановился?', [job, Tasks.option('guard'), bye].filter(Boolean));
    }
    if (id === 'villager1') return say(f.ending === 'keep' ? 'Ты... знаешь, я пойду овец проверю. Овцы далеко. Очень далеко.' : cycle(['Овцы опять ушли к лесу. Волки их не тронули. Меня — почти. Овцы, кажется, договорились.', 'В шахте по ночам светится. Лунные цветы, говорят. Или чьи-то глаза. Я туда не хожу, у меня овцы.', 'Марта печёт хлеб по утрам. Лучший на перевале. Конкурентов, правда, нет, но хлеб честно хороший.', f.banditsBribed ? 'Видел вчера Хродгара у скал. Оле говорит — показалось. Мне и мор в прошлом году показался.' : 'Оле третий год обещает разобраться с лесом. Лес третий год не в курсе.', 'Ты, говорят, герой. Это хорошо. Овец не пасёшь? Нет? Жаль. Герои у нас есть, а пастухов не хватает.']));
    if (id === 'villager2') {
      if (q.twoInMine === 1 && c('note_mine')) return say('Что у тебя в руке? Дай... «Скажите Грете». Это почерк Торвальда. Моего мужа. Он был в шахте, когда... Хальвар сказал, что их завалило.', [{ label: 'Хальвар завалил вход сам', main: true, go: () => { q.twoInMine = 2; f.mineTruth = 'greta'; removeItem('note_mine'); log('Задание выполнено: Двое в шахте', 'gold'); SFX.quest(); addItem('helmet_iron', 1, false, { plus: 1 }); return say('...Двадцать лет. Двадцать лет он пил в таверне напротив моего окна и здоровался со мной по утрам.\n\nСпасибо, что сказал. Убивать не буду — я женщина хозяйственная, а от трупа одни расходы. Буду просто смотреть на него. Каждый день. Долго.\n\nВозьми, это Торвальда. Ему уже ни к чему, а ты, судя по виду, доспехами не избалован.', [{ label: 'Взять', go: () => 'close' }]); } }, { label: 'Это просто старая записка', go: () => say('...Да. Наверное. Иди, странник.') }]);
      return say(f.mineTruth === 'greta' ? 'Я смотрю на него каждый день. Он знает. Он теперь садится спиной к окну.' : f.mineTruth === 'osvin' ? 'Хальвар ушёл. Мог бы и сам сказать. Двадцать лет мог, у него было столько вечеров.' : q.seal === 2 && f.ending !== 'keep' ? 'У часовни тише стало. Спасибо, милок. Свечку за тебя поставлю — маленькую, большие дорогие.' : f.ending === 'keep' ? 'У часовни воет. Хуже прежнего. Что ты там сделал, милок? Нет, не рассказывай. Я потом не усну.' : cycle(['Не ходи ночью к часовне, милок. Оттуда воет. Днём тоже воет, но днём не так обидно.', 'Ильва мне спину вылечила. Золотые руки. Цены, правда, тоже.', 'Муж в шахте сгинул. Двадцать лет. Хальвар один вышел — и с тех пор пьёт, будто это ему тяжело.', 'Торвальд ходил в крипту молиться. Я думала — молиться.']));
    }
    if (id === 'drunk') {
      let job;
      if (q.cousin === 0 && !f.chiefDead) job = { label: 'Ты знаешь Хродгара?', go: () => say('...Тише ты. Знаю. Двоюродный брат. Мы с ним овец пасли, пока он не решил, что грабить прибыльнее. Он, между нами, был прав, и это самое обидное.\n\nОле хочет его голову. Я хочу, чтобы он ушёл живым. Скажи ему: Свен зовёт домой, к матери, в долину за перевалом.\n\nОн послушает. Может быть. Он вообще-то никогда меня не слушал, но мать — другое дело, мать страшнее разбойников.', [startQ('cousin', 'Двоюродный брат', 'Скажу'), { label: 'Не лезу в семейное', go: () => 'close' }]) };
      else if (q.cousin === 1) job = f.chiefGone ? done('cousin', 'Двоюродный брат', () => { addItem('ring_chief'); }, 'Хродгар ушёл', 'Ушёл?.. Живой? Держи дедов перстень. Хродгар свой пропил, я свой сохранил — вот и вся разница между разбойником и приличным человеком.') : f.chiefDead ? done('cousin', 'Двоюродный брат', () => { }, 'Хродгар мёртв', '...Понятно. Марта, ещё кружку. Нет. Две.') : { label: 'Про брата', go: () => say('Лагерь у скал, на северо-востоке. Скажи ему про мать.') };
      else job = { label: 'Как ты?', go: () => say(f.chiefGone ? 'Трезвый. Третий день. Не спрашивай, не поможет.' : 'Ик. Это, между прочим, полноценный ответ. Ёмкий.') };
      const greet = cycle(['Торвальд рассказывал — до того, как сгинул, — что в крипте плачет девка в белом и ищет медальон. Я не верил. Теперь воет кто-то. Может, это она нашла медальон и ей не понравилось.', 'Марта, ещё кружку!.. А, это ты. Ты не Марта. Ты хуже: ты трезвый.', f.chiefDead ? 'Хродгар... брат... а Оле — сволочь. Это, кстати, независимые утверждения, оба верные.' : 'Оле говорит — разбойники. А я говорю — люди. Голодные. Разница в том, кому из них ты попался.', 'Знаешь, чем герой отличается от пьяницы? Герою наливают бесплатно. Мне — нет. Делай выводы, странник.'], 30);
      return say(greet, [job, bye].filter(Boolean));
    }
    // ---- Атаман (мирный разговор) ----
    if (id === 'chief') {
      const fight = { label: 'К оружию', go: () => { const en = L.enemies.find(e => e.id === 'f_chief'); if (en) { en.friendly = false; en.state = 'chase'; en.talk = null; for (const o of L.enemies) if (o.type.startsWith('bandit') && dist2(o.x, o.z, P.x, P.z) < 9) { o.friendly = false; o.state = 'chase'; } } return 'close'; } };
      const opts = [];
      if (q.cousin === 1) opts.push({ label: 'Свен зовёт домой, к матери', main: true, go: () => say('...Свен. Пьяница. Он ещё жив? Удивительно, у него была фора в двадцать лет и кружка в каждой руке.\n\nМать, значит. Ладно. Скажу честно, потому что вру я только за деньги: моим людям нужно золото на дорогу. Идея «уйти в никуда ради семейных чувств» их не вдохновляет.\n\nПолторы сотни. Дашь — уйдём за перевал. Не дашь — разговор окончен, и это не угроза, а расписание.', [{ label: `Дать 150 золота (есть ${G.gold})`, main: true, go: () => { if (G.gold < 150) return say('Не хватает. Приходи, когда будет.', [bye]); G.gold -= 150; f.chiefGone = 1; log('Хродгар уводит шайку с перевала', 'gold'); gainXp(120); SFX.quest(); const gone = []; for (const en of L.enemies) if (en.id === 'f_chief' || en.type.startsWith('bandit')) gone.push(en); for (const en of gone) { removeMesh(en.mesh); L.enemies.splice(L.enemies.indexOf(en), 1); G.killed[en.id] = 999; } Quests.check(); return say('...Передай Свену: пусть не пьёт. Он не перестанет, но передай, мне будет приятно.\n\nСундук в палатке твой. Замок откроешь сам — ключ я, к сожалению, съел. Шучу. Потерял.'); } }, { label: 'Нет', go: () => 'close' }]) });
      if (q.bandits === 1 && !f.chiefBribed) opts.push({ label: 'Оле платит за твою голову', go: () => say('Сотню? Полторы? Слушай сюда. Я дам тебе сто прямо сейчас, а ты скажешь Оле, что я сбежал.\n\nОн поверит. Он верит всему, что позволяет не заходить в лес дальше первой сосны.\n\nМы уйдём поглубже, никто не пострадает, все при своём. Это называется дипломатия, и на перевале она работает лучше меча.', [{ label: 'Взять 100 золота', go: () => { G.gold += 100; f.chiefBribed = 1; log('+100 золота. Ты обещал соврать Оле.', 'gold'); return say('Умно. Не приходи больше.'); } }, fight]) });
      opts.push(fight); opts.push(bye);
      return say(f.chiefBribed ? 'Я сказал — не приходи. Сотню ты получил, совесть я тебе не продавал, она в комплект не входит.' : 'Ещё шаг — и мои люди сделают из тебя подушечку для иголок. Но ты пришёл один, без Оле и без меча наголо, а значит — либо дурак, либо с предложением. Говори, я угадаю по ходу.', opts);
    }
    // ---- Трактирщица ----
    if (id === 'innkeeper') {
      const trade = { label: 'Купить еды', go: () => { Shop.open('innkeeper'); return 'close'; } };
      const rest = { label: 'Про ночлег', go: () => say(q.seal >= 1 ? 'Кровати у стены. С тебя не возьму — Освин сказал, ты за нас в крипту полезешь. Не возьму за кровать. За еду возьму. За эль возьму дважды, потому что ты его выпьешь дважды.\n\nОчаг твой: жарь мясо, вари похлёбку. Только не жарь то, что принёс из крипты.' : 'Кровать — десять монет за ночь. Очаг бесплатно, потому что дрова твои.') };
      let job;
      if (q.merchant === 0 && q.arrow !== 2 && !f.ansgarGone) job = { label: 'Ты чем-то встревожена', go: () => say('Эйнар. Торговец. Мой... друг. Да, друг, и не делай такое лицо, у меня и так вся деревня делает такое лицо.\n\nУшёл неделю назад к охотнику за шкурами и не вернулся. Оле говорит — разбойники. Оле всегда говорит «разбойники», это его способ закрыть тему.\n\nПройди по тропе за восточными воротами. Поищи хоть что-нибудь. Заплачу. Не золотом сердца, а нормальным золотом, не волнуйся.', [startQ('merchant', 'Пропавший торговец', 'Я поищу'), { label: 'Сочувствую, но нет', go: () => 'close' }]) };
      else if (q.merchant === 1) job = c('letter') ? { label: 'Отдать письмо', main: true, go: () => { removeItem('letter'); q.merchant = 2; G.gold += 60; addItem('stew', 2); log('+60 золота', 'gold'); log('Задание выполнено: Пропавший торговец', 'gold'); SFX.quest(); if (q.arrow === 0) q.arrow = 1; return say('«...не разбойники». Его рука. Он даже умер лаконично — всю жизнь экономил на чернилах.\n\nНе разбойники. Тогда кто? Он шёл к Ансгару. Ансгар был ему должен — сорок монет, Эйнар ныл об этом каждый вечер.\n\nЯ не прошу. Я вообще стараюсь никого ни о чём не просить, дешевле выходит. Но если узнаешь — скажи. Возьми за хлопоты. И похлёбка от заведения: она всё равно пригорела.'); } } : { label: 'Про Эйнара', go: () => say('Тропа за восточными воротами. Он должен был идти к охотнику Ансгару на юг, мимо камней.') };
      else if (q.arrow === 2 && !f.martaTold) job = { label: 'Про Ансгара', main: true, go: () => { f.martaTold = 1; if (f.arrowTruth) { G.gold += 100; log('+100 золота', 'gold'); return say(f.ansgarDead ? 'В спину. Значит, знал, что делает.\n\n...Мёртв. Хорошо. Нет — не хорошо. Ничего не хорошо. Но спасибо. Возьми — это то, что Эйнар оставил здесь на хранение. Ему уже не нужно.' : 'В спину. Значит, знал, что делает.\n\nУшёл? Из-за сорока монет и письма, которое я даже не дочитала... Спасибо, что не убил его. Или нет. Я не знаю. Возьми — Эйнар оставлял здесь деньги.'); } return say('Ты выяснил? ...Нет? Ладно. Может, и правда разбойники.', [bye]); } };
      else job = { label: 'Про Эйнара', go: () => say(f.arrowTruth ? 'Хожу к камням по утрам. Кладу хлеб. Глупо, да? Птицы, между прочим, довольны — хоть кому-то от этой истории польза.' : f.chiefDead ? 'Хродгар мёртв, говорят. Я не рада. Но мне легче.' : 'Разбойники. Хродгар. Оле обещал, что разберётся — но у него одни ворота на уме.') };
      return say('Добро пожаловать в «Пепельный лис». Хлеб свежий, похлёбка горячая, кровати чистые — по меркам перевала, где чистым считается всё, что не шевелится.\n\nЧто-то ещё?', [trade, job, rest, Tasks.option('innkeeper'), bye].filter(Boolean));
    }
    // ---- Рудокоп ----
    if (id === 'miner') {
      let job;
      if (q.twoInMine === 1 && c('note_mine')) job = { label: 'Записка из шахты', main: true, go: () => say('...Где ты это взял. Отдай. ОТДАЙ.\n\n...Ладно. Да. Пауки шли за нами, я обрушил крепь. Торвальд и Ульф остались по ту сторону. Я слышал, как они кричали. Три дня.\n\nЗнаешь, что самое мерзкое? Я поступил правильно. Если бы не обрушил — сожрали бы всю деревню. Я двадцать лет каждое утро просыпаюсь правым, и от этого только хуже.\n\nЧто ты хочешь? Денег? Дам. Только не говори Грете.', [{ label: 'Молчать (100 золота)', go: () => { q.twoInMine = 2; f.mineTruth = 'silent'; removeItem('note_mine'); G.gold += 100; log('+100 золота', 'gold'); log('Задание выполнено: Двое в шахте', 'gold'); return say('...Спасибо. Нет. Не спасибо. Уходи.'); } }, { label: 'Грета должна знать', go: () => say('Тогда иди и скажи ей. Я буду здесь. Я всегда здесь.') }, { label: 'Скажу старосте', go: () => { q.twoInMine = 2; f.mineTruth = 'osvin'; f.minerGone = 1; removeItem('note_mine'); if (q.mine === 1) { q.mine = 2; if (c('pickaxe_old')) f.mineDone = 1; log(c('pickaxe_old') ? 'Задание выполнено: Старая шахта' : 'Старая шахта: Хальвара больше нет. Кирка — твоя, если найдёшь.', 'gold'); } log('Задание выполнено: Двое в шахте', 'gold'); const n = L.npcs.find(n => n.def.id === 'miner'); if (n) { removeMesh(n.mesh); L.npcs.splice(L.npcs.indexOf(n), 1); } return say('...Освин меня выгонит. Правильно. Двадцать лет я ждал, кто выгонит.\n\nКирку оставь себе.'); } }]) };
      else if (q.mine === 0) job = { label: 'Что случилось с шахтой?', go: () => say('Пауки. С собаку размером. Мы ушли, когда Матка сожрала двоих, — и, поверь, это был единодушный совет директоров.\n\nТам осталась кирка моего отца, в самой глубине, где Матка свила гнездо. Принеси — сто монет. И руду бери сколько унесёшь: я с шахтой закончил, а шахта, кажется, закончила со мной.', [startQ('mine', 'Старая шахта', 'Я спущусь'), { label: 'Не сейчас', go: () => 'close' }]) };
      else if (q.mine === 1) job = c('pickaxe_old') ? done('mine', 'Старая шахта', () => { f.mineDone = 1; G.gold += 100; addItem('ore', 3); }, 'Показать кирку', '«Не бойся темноты». Его почерк. Отец был человек кратких формулировок и полного отсутствия чувства момента.\n\nОставь кирку себе. У тебя она в деле, у меня — на стене над кроватью, откуда будет каждую ночь на меня смотреть. Вот, руды на первое время.') : { label: 'Про шахту', go: () => say(f.queenDead ? 'Матка мертва? Тогда кирка где-то в её логове, в южном зале. Ищи.' : 'Вход в шахту — старые штольни на севере леса, в скалах за гоблинским костром. Пауки плюются ядом — возьми противоядие у Ильвы. Матка сидит в самом дальнем зале, на юго-востоке.') };
      else job = { label: 'Про руду', go: () => say('Жилы восстанавливаются, если дать им день. Гора у нас терпеливая, не то что люди.\n\nРуду неси Брандту. Самоцветы — в глубине, синие жилы. И не смотри там по сторонам слишком долго: в темноте всё выглядит как что-то, а потом оказывается, что это и было что-то.') };
      return say(f.mineTruth === 'greta' ? '...Она смотрит. Каждый день. Ты сказал ей. Ладно. Это, наверное, справедливо. Справедливость — редкая дрянь: приходит через двадцать лет и садится напротив.' : 'Хальвар, бывший рудокоп. Бывший — потому что шахта теперь паучья, а я теперь в основном пьющий.', [job, bye]);
    }
    // ---- Охотник ----
    if (id === 'hunter') {
      const trade = { label: 'Торговать', go: () => { Shop.open('hunter'); return 'close'; } };
      let job;
      if (q.bear === 0) job = { label: 'Есть работа?', go: () => say('Шатун. Медведь, который не лёг на зиму. Злой, голодный и, судя по всему, глубоко разочарованный в жизни — как все, кому не дали выспаться.\n\nЗадрал двух моих собак. Логово на юго-востоке, за мёртвыми соснами. Убьёшь — принеси коготь, сделаю оберег. Тебе же и отдам, мне-то он зачем: я в лес хожу с луком, а не с надеждой.', [startQ('bear', 'Медведь-шатун', 'Убью'), { label: 'Не сейчас', go: () => 'close' }]) };
      else if (q.bear === 1) job = c('bear_claw') ? done('bear', 'Медведь-шатун', () => { G.gold += 80; log('+80 золота', 'gold'); log('Коготь шатуна теперь оберег — надень его.', 'blue'); }, 'Показать коготь', 'Коготь... Здоровый был зверь. Больше меня. Больше тебя. Теперь — меньше нас обоих.\n\nДержи монеты и носи коготь. Я его заговорил, как умел. Умел я так себе, но зверь был хороший, он вытянет.') : { label: 'Про шатуна', go: () => say('Юго-восток, за мёртвыми соснами, где кости. Кости не мои, если что.\n\nПосле удара лапой он на миг замирает — вот тогда бей. Заревёт — отходи, сейчас бросится. Это, между прочим, полноценная тактика, а не то, что делаешь ты: подбегаешь и машешь.') };
      else job = { label: 'Про оберег', go: () => say('Носи на шее. Медведь в нём ещё злится, но теперь — в твою пользу. Договориться со зверем после смерти проще, чем с человеком при жизни.') };
      const opts = [trade, job, Tasks.option('hunter')].filter(Boolean);
      if (q.arrow === 1 && c('ledger')) opts.push({ label: f.ansgarConfessed ? 'Ты не ответил: уйдёшь или...' : 'Ты убил Эйнара', main: true, go: () => say(f.ansgarConfessed ? 'Я жду. Дай уйти — или подними лук.' : '...Книга. Ты вскрыл мой сундук.\n\nОн пришёл за сорока монетами — и не за ними. Сказал: «Марта знает, что ты ей писал. Ей смешно». Повернулся и пошёл к камням. А у меня лук был в руке, и он шёл спиной... Я не решал. Рука решила.\n\n' + (f.chiefDead ? 'Хродгар мёртв — можно всё свалить на него. Никто не узнает.' : 'Хродгар рядом — все и так думают на него.') + ' Что ты сделаешь?', [{ label: 'Марта узнает правду', main: true, go: () => { f.ansgarConfessed = 1; return say('Тогда мне тут не жить. Дай уйти — я не подниму лук. Или подними свой.', [{ label: 'Уходи и не возвращайся', go: () => { q.arrow = 2; f.arrowTruth = 1; f.ansgarGone = 1; if (q.bear === 1) { q.bear = 2; f.bearNoAnsgar = 1; } const n = L.npcs.find(n => n.def.id === 'hunter'); if (n) { removeMesh(n.mesh); L.npcs.splice(L.npcs.indexOf(n), 1); } log('Задание выполнено: Стрела в спину', 'gold'); SFX.quest(); return 'close'; } }, { label: 'Ты ответишь здесь', go: () => { q.arrow = 2; f.arrowTruth = 1; f.ansgarGone = 1; f.ansgarFight = 1; if (q.bear === 1) { q.bear = 2; f.bearNoAnsgar = 1; } const n = L.npcs.find(n => n.def.id === 'hunter'); if (n) { removeMesh(n.mesh); L.npcs.splice(L.npcs.indexOf(n), 1); } const en = spawnEnemy({ id: 'f_ansgar', type: 'hunterFoe', x: 11, z: 36, name: 'Охотник Ансгар' }); en.state = 'chase'; log('Задание выполнено: Стрела в спину', 'gold'); return 'close'; } }]); } }, { label: 'Молчание стоит денег', go: () => { q.arrow = 2; f.arrowSilent = 1; G.gold += 60; log('+60 золота за молчание', 'gold'); log('Задание выполнено: Стрела в спину', 'gold'); return say('Шестьдесят. Всё, что есть. Уходи.'); } }]) });
      opts.push(bye);
      return say(f.arrowSilent ? '...Ты что-то забыл?' : cycle(['Тихо у меня. Мясо есть, шкуры беру. Разбойники не суются — знают, что стреляю. Люди вообще уважают только два аргумента, и оба летят по прямой.', 'Эйнар? Торговец? Заходил. Ушёл к камням. Больше не видел. ...Что ты так смотришь.', 'Ночью в лесу холодно. Возьми плащ — или сшей из шкур. Шкуры продам. Со скидкой не продам.']), opts);
    }
    // ---- Призрак ----
    if (id === 'ghost') {
      if (q.locket === 0) return say('...ты живой? Тёплый.\n\nЯ Элинор, дочь Освина-старшего. Меня положили сюда, потому что я любила не того: простого рудокопа. Отец сказал — не на общем кладбище. Отец вообще многое говорил, и всё почему-то про кладбища.\n\nОни забрали медальон с его прядью. Он где-то в южных залах, я слышу, как он звенит. Двести лет слышу. Знаешь, что хуже вечности? Вечность с одним и тем же звуком.\n\nНайди его — и я уйду. Я очень устала стоять.', [startQ('locket', 'Неупокоенная', 'Я найду'), { label: 'Уйти', go: () => 'close' }]);
      if (q.locket === 1) return c('locket') ? say('Это он... его прядь. Спасибо, живой.\n\nВозьми то, что я умела при жизни: холод, который слушается. Пригодится там, куда я больше не пойду, — то есть вообще везде.\n\nИ передай брату... нет. Ничего не передавай. Пусть сам спускается и спрашивает у отца. У них, я слышала, накопилось.', [{ label: 'Отдать медальон', main: true, go: () => { removeItem('locket'); q.locket = 2; f.ghostGone = 1; if (!G.spells.includes('ice')) G.spells.push('ice'); log('Изучено заклинание: Ледяная стрела (выбор — в сумке или долгим нажатием на кнопку)', 'blue'); log('Задание выполнено: Неупокоенная', 'gold'); SFX.quest(); const n = L.npcs.find(n => n.def.id === 'ghost'); if (n) { removeMesh(n.mesh); L.npcs.splice(L.npcs.indexOf(n), 1); } return 'close'; } }]) : say('Южные залы. Там, где могилы без имён. Он звенит. Нет, я не могу показать точнее — я двести лет стою на одном месте, у меня с ориентированием так себе.');
      return null;
    }
    return null;
  }
};

const Shop = {
  stock: { smith: ['dagger_iron', 'sword_iron', 'axe_wood', 'spear_wood', 'mace_iron', 'pickaxe', 'shovel', 'armor_leather', 'armor_chain', 'helmet_leather', 'helmet_iron', 'shield_wood', 'cloak', 'lockpick', 'ingot'], healer: ['potion_hp', 'potion_mp', 'potion_g', 'potion_warm', 'bandage', 'rune_life', 'flask'], innkeeper: ['bread', 'stew', 'meatCooked', 'ale', 'flask'], hunter: ['meat', 'meatCooked', 'bandage', 'axe_wood', 'cloak'] },
  names: { smith: 'Кузница Брандта', healer: 'Лавка Ильвы', innkeeper: 'Таверна «Пепельный лис»', hunter: 'Стоянка Ансгара' },
  mod: 1, haggled: false, sellConfirm: null,
  open(id) { this.id = id; this.buyConfirm = null; G.haggled = G.haggled || {}; this.haggled = G.haggled[id] === G.day; this.mod = this.haggled ? (G.haggleMod && G.haggleMod[id]) || 1 : 1; this.sellConfirm = null; $('shopName').textContent = this.names[id]; this.render(); UI.show('shop'); },
  price(it) { return Math.max(1, Math.round(it.value * this.mod * (1 - perkLvl('haggler') * 0.12))); },
  render() {
    const buy = $('shopList'), sell = $('shopSell'); buy.innerHTML = '<h3>Купить (второй тап — подтвердить)</h3>'; sell.innerHTML = '<h3>Продать (35% цены, второй тап — подтвердить)</h3>';
    for (const id of this.stock[this.id]) { const it = ITEMS[id]; const d = document.createElement('div'); d.className = 'item' + (G.gold < this.price(it) ? ' dim' : ''); const armed = this.buyConfirm === id; if (armed) d.classList.add('sel'); d.innerHTML = `<span>${UI.icon(it.icon)}${it.name} <span class="q">${UI.itemInfo(it)}</span></span><span class="q">${armed ? '<b>купить?</b> ' : ''}${this.price(it)} зол.</span>`; d.onclick = () => { if (G.gold < this.price(it)) { log('Не хватает золота', 'red'); return; } if (!armed) { this.buyConfirm = id; this.render(); return; } this.buyConfirm = null; G.gold -= this.price(it); addItem(id); SFX.gold(); this.render(); }; buy.appendChild(d); }
    for (const s of G.inv) { const it = ITEMS[s.id]; if (it.type === 'key' || it.quest || it.value <= 0 || Object.values(G.eq).includes(s.uid)) continue; const cond = s.dur !== undefined && it.maxDur ? 0.4 + 0.6 * Math.max(0, s.dur) / it.maxDur : 1, bonus = 1 + (s.plus || 0) * 0.35 + (s.ench ? 0.5 : 0); const price = Math.max(1, Math.floor(it.value * (it.type === 'gem' ? 0.2 : 0.35) * cond * bonus * (this.haggled && this.mod < 1 ? 1.15 : 1))); const d = document.createElement('div'); d.className = 'item' + (this.sellConfirm === s.uid ? ' sel' : ''); d.innerHTML = `<span>${UI.icon(it.icon)}${itemName(s)}${s.q > 1 ? ' ×' + s.q : ''}${this.sellConfirm === s.uid ? ' — продать?' : ''}</span><span class="q">${price} зол.</span>`; d.onclick = () => { if (this.sellConfirm !== s.uid) { this.sellConfirm = s.uid; this.render(); return; } if (s.q > 1) s.q--; else removeInst(s.uid); G.gold += price; SFX.gold(); this.sellConfirm = null; this.render(); }; sell.appendChild(d); }
    $('shopGold').textContent = `У тебя ${G.gold} золота${this.mod !== 1 ? ' · цены ×' + this.mod.toFixed(2) : ''}`;
    const hb = $('shopHaggle'); hb.style.display = this.haggled ? 'none' : ''; hb.onclick = () => { this.haggled = true; G.haggled[this.id] = G.day; Mini.haggle(ok => { this.mod = ok ? 0.85 : 1.1; G.haggleMod = G.haggleMod || {}; G.haggleMod[this.id] = this.mod; this.render(); UI.show('shop'); }); };
  }
};
